	@ParameterizedTest(name = "alias source work with direct adjacency={0}")
	@ValueSource(booleans = { false, true })
	void aliasJoinSourceWorkGrowsNearLinearly(boolean adjacency) throws Exception {
		Measurement smaller = measure(adjacency, 16, true);
		Measurement larger = measure(adjacency, 32, false);

		assertThat(smaller.automaticWork())
				.as("the selected automatic native route must expose a supported physical work counter")
				.isPositive();
		assertThat(larger.automaticWork())
				.as("the selected automatic native route must expose a supported physical work counter")
				.isPositive();
		if (smaller.automaticWorkMetric().equals(larger.automaticWorkMetric())) {
			assertThat(larger.automaticWork())
					.as("doubling inputs should keep the same automatic-route work counter near-linear; metric=%s, "
							+ "small=%s, large=%s\nsmall plan:\n%s\nlarge plan:\n%s",
							smaller.automaticWorkMetric(), smaller.automaticWork(), larger.automaticWork(),
							smaller.nativeTelemetry(), larger.nativeTelemetry())
					.isLessThanOrEqualTo(smaller.automaticWork() * 3);
		}
		assertThat(larger.scannedRows())
				.as("doubling inputs should keep observed physical rows scanned by the real native nested-loop source "
						+ "near-linear; source scans small=%s, large=%s, adjacency=%s\nsmall plan:\n%s\nlarge plan:\n%s",
						smaller.scannedRows(), larger.scannedRows(),
						adjacency,
						smaller.nestedLoopTelemetry(), larger.nestedLoopTelemetry())
				.isLessThanOrEqualTo(smaller.scannedRows() * 3);
		if (smaller.candidateRows() > 0 && larger.candidateRows() > 0) {
			assertThat(larger.candidateRows())
					.as("when both selected routes expose candidate counts, doubling inputs should keep them near-linear; "
							+ "small=%s, large=%s, adjacency=%s\nsmall plan:\n%s\nlarge plan:\n%s",
							smaller.candidateRows(), larger.candidateRows(), adjacency,
							smaller.nativeTelemetry(), larger.nativeTelemetry())
					.isLessThanOrEqualTo(smaller.candidateRows() * 3);
		}
	}

