	@ParameterizedTest(name = "fixed-key object-leading lookup with adjacency={0}, indexes={1}")
	@MethodSource("objectBoundAliasConfigurations")
	void fixedObjectAlias16KeysDoNotScanUnrelatedData(boolean adjacency, String indexConfiguration) throws Exception {
		FixedKeyAliasMeasurement smaller = measureFixedKeyObjectAlias(adjacency, indexConfiguration, 16, 128);
		FixedKeyAliasMeasurement larger = measureFixedKeyObjectAlias(adjacency, indexConfiguration, 16, 256);
		assertBoundedNativeWork(smaller.sourceWork(), larger.sourceWork(), "fixed 16 object keys");
		for (String route : List.of("automatic", "nestedLoop", "irKernelInterpreted")) {
			ObjectBoundSourceWork small = smaller.route(route);
			ObjectBoundSourceWork large = larger.route(route);
			boolean mayLackMeasurements = route.equals("automatic")
					|| (adjacency && route.equals("irKernelInterpreted"));
			if (mayLackMeasurements && !small.workAvailable() && !large.workAvailable()) {
				assertThat(small.telemetry())
						.as("%s explicitly reports unavailable physical source measurements", route)
						.contains("NO_MEASURED_STATEMENT_ACCESS_COMPLETED");
				assertThat(large.telemetry())
						.as("%s reports the same unavailable measurement at both sizes", route)
						.contains("NO_MEASURED_STATEMENT_ACCESS_COMPLETED");
				if (adjacency) {
					assertThat(small.selectedSourceAccesses()).contains("source: IN_MEMORY_ADJACENCY");
					assertThat(large.selectedSourceAccesses()).contains("source: IN_MEMORY_ADJACENCY");
				}
				continue;
			}
			assertThat(small.workAvailable())
					.as("%s exposes selected physical source work for 16 keys and 128 unrelated rows: %s", route,
							small.summary())
					.isTrue();
			assertThat(large.workAvailable())
					.as("%s exposes selected physical source work for 16 keys and 256 unrelated rows: %s", route,
							large.summary())
					.isTrue();
			assertThat(small.work()).as("%s work is positive at the smaller size", route).isPositive();
			assertThat(large.work()).as("%s work is positive at the larger size", route).isPositive();
			assertThat(large.metricKind())
					.as("%s reports the same physical work unit at both sizes", route)
					.isEqualTo(small.metricKind());
			assertThat(large.work())
					.as("%s selected %s work remains bounded as only unrelated rows double; small=%s, large=%s",
							route, small.metricKind(),
							small.summary(), large.summary())
					.isLessThanOrEqualTo(small.work() + 4);
		}
	}

