	private NativeSourceWork measureDirectBoundObject(boolean adjacency, String indexConfiguration, int values)
			throws Exception {
		String indexLabel = indexConfiguration.equals("default-spoc-posc") ? "default" : "rich-ospc";
		String suffix = adjacency + "-" + indexLabel + "-size-" + values;
		Path actualPath = directory.resolve("direct-object-actual-" + suffix);
		Path genericPath = directory.resolve("direct-object-generic-" + suffix);
		LmdbStoreConfig actualConfig = indexLabel.equals("rich-ospc")
				? new LmdbStoreConfig("spoc,posc,ospc")
				: new LmdbStoreConfig();
		actualConfig.setNativeEvaluationEnabled(true).setDirectAdjacencyEnabled(adjacency);
		LmdbStore actualStore = new LmdbStore(actualPath.toFile(), actualConfig);
		LmdbStore genericStore = new LmdbStore(genericPath.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(false));
		SailRepository actual = new SailRepository(actualStore);
		SailRepository generic = new SailRepository(genericStore);
		actual.init();
		generic.init();
		try {
			loadObjectBoundAlias(actual, values, 1);
			loadObjectBoundAlias(generic, values, 1);
			if (adjacency) {
				assertThat(actualStore.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS))
						.as(actualStore.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}
			NativeSourceWork sourceWork;
			List<BindingSet> expected = List.of(
					expectedRow("right", iri("urn:object-alias:left:0"), "predicate", OBJECT_LEFT_PREDICATE),
					expectedRow("right", iri("urn:object-alias:right:0:0"), "predicate", OBJECT_MATCH_PREDICATE));
			try (var nativeConnection = actual.getConnection(); var genericConnection = generic.getConnection()) {
				TupleQuery genericQuery = genericConnection.prepareTupleQuery(DIRECT_OBJECT_LOOKUP_QUERY);
				genericQuery.setBinding("focus", iri("urn:object-alias:focus:0"));
				((SailQuery) genericQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> genericRows = evaluate(genericQuery);

				SailTupleQuery nativeQuery = (SailTupleQuery) nativeConnection
						.prepareTupleQuery(DIRECT_OBJECT_LOOKUP_QUERY);
				nativeQuery.setBinding("focus", iri("urn:object-alias:focus:0"));
				nativeQuery.setForcedLmdbExecutionStrategy("nestedLoop");
				((SailQuery) nativeQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> nativeRows = evaluate(nativeQuery);
				String telemetry = nativeQuery.explain(Explanation.Level.Telemetry).toString();
				String selected = selectedObjectOnlyAccesses(telemetry);
				long sourceRowsScanned = scannedRows(telemetry);
				long sourceRowsMatched = matchedRows(telemetry);
				assertThat(bag(genericRows)).as("independent direct-object bag")
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				assertThat(bag(nativeRows)).as("native direct-object bag")
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				assertThat(telemetry).as("direct object lookup executed its forced native route")
						.contains("strategy: nestedLoop", "nativeInvocationsActual=1");
				assertThat(selected).as("the direct bound object reached a selected source access\n%s", telemetry)
						.contains("outcome: SELECTED", "subject: UNBOUND", "predicate: UNBOUND", "object: BOUND");
				assertThat(sourceRowsScanned).as("the selected source reports actual scanned rows\n%s", telemetry)
						.isPositive();
				assertThat(sourceRowsMatched).as("source matches are counted separately from scans\n%s", telemetry)
						.isEqualTo(expected.size());
				assertThat(sourceRowsScanned).as("object-keyed access visits exactly its two matching statements")
						.isEqualTo(sourceRowsMatched);
				if (adjacency) {
					assertThat(selected)
							.as("the adjacency control used its object-keyed in-memory source\n%s", telemetry)
							.contains("source: IN_MEMORY_ADJACENCY");
				} else {
					assertThat(selected)
							.as("persistent object-bound access is selected under either configured preference")
							.contains("source: LMDB");
				}
				// Observe native calls only after the query checks: instrumentation overhead must not train their
				// adaptive source selection. The raw control measures the same bound-object access independently.
				sourceWork = measureBoundObjectSource(actualStore,
						List.of(iri("urn:object-alias:focus:0")), adjacency);
				Path evidence = Files.createDirectories(Path.of("logs", "workbench-native-fast-paths",
						"physical-prefix-merged-20261027", "object-alias", "direct-bound-control",
						"adjacency-" + adjacency + "-" + indexLabel, "size-" + values));
				Files.writeString(evidence.resolve("query.rq"), DIRECT_OBJECT_LOOKUP_QUERY);
				Files.writeString(evidence.resolve("expected.rows.txt"), canonicalRows(expected).toString());
				Files.writeString(evidence.resolve("generic.rows.txt"), canonicalRows(genericRows).toString());
				Files.writeString(evidence.resolve("native.rows.txt"), canonicalRows(nativeRows).toString());
				Files.writeString(evidence.resolve("telemetry.txt"), telemetry);
				Files.writeString(evidence.resolve("native-source-work.txt"), sourceWork.toString());
			}
			return sourceWork;
		} finally {
			actual.shutDown();
			generic.shutDown();
		}
	}

	private static Stream<Arguments> objectBoundAliasConfigurations() {
		return Stream.of(Arguments.of(false, "default-spoc-posc"), Arguments.of(true, "default-spoc-posc"),
				Arguments.of(false, "rich-spoc-posc-ospc"), Arguments.of(true, "rich-spoc-posc-ospc"));
	}

	@ParameterizedTest(name = "positive UNION alias source work with direct adjacency={0}")
	@ValueSource(booleans = { false, true })
	void unionAliasCorrelatedWorkGrowsNearLinearly(boolean adjacency) throws Exception {
		SoftAssertions softly = new SoftAssertions();
		UnionMeasurement sourceSmall = measureUnion(adjacency, 16, UNION_SOURCE_QUERY, "source", true, softly);
		UnionMeasurement sourceLarge = measureUnion(adjacency, 32, UNION_SOURCE_QUERY, "source", false, softly);
		UnionMeasurement targetSmall = measureUnion(adjacency, 16, UNION_TARGET_QUERY, "target", false, softly);
		UnionMeasurement targetLarge = measureUnion(adjacency, 32, UNION_TARGET_QUERY, "target", false, softly);
		AdverseMeasurement rareLeftSmall = measureAdverse(adjacency, 16);
		AdverseMeasurement rareLeftLarge = measureAdverse(adjacency, 32);

		if (!adjacency) {
			assertCompletedLmdbUnionWork(softly, "source alias automatic", sourceSmall.automaticLmdb(),
					sourceLarge.automaticLmdb());
			assertCompletedLmdbUnionWork(softly, "source alias forced nestedLoop", sourceSmall.nestedLoopLmdb(),
					sourceLarge.nestedLoopLmdb());
			assertCompletedLmdbUnionWork(softly, "target alias automatic", targetSmall.automaticLmdb(),
					targetLarge.automaticLmdb());
			assertCompletedLmdbUnionWork(softly, "target alias forced nestedLoop", targetSmall.nestedLoopLmdb(),
					targetLarge.nestedLoopLmdb());
		}
		softly.assertThatCode(() -> assertNearLinearWork("source alias automatic", adjacency,
				sourceSmall.automatic(), sourceLarge.automatic(), true)).doesNotThrowAnyException();
		softly.assertThatCode(() -> assertNearLinearWork("source alias forced nestedLoop", adjacency,
				sourceSmall.nestedLoop(), sourceLarge.nestedLoop(), false)).doesNotThrowAnyException();
		softly.assertThatCode(() -> assertNearLinearWork("target alias automatic", adjacency,
				targetSmall.automatic(), targetLarge.automatic(), true)).doesNotThrowAnyException();
		softly.assertThatCode(() -> assertNearLinearWork("target alias forced nestedLoop", adjacency,
				targetSmall.nestedLoop(), targetLarge.nestedLoop(), false)).doesNotThrowAnyException();
		softly.assertThatCode(() -> assertNearConstantWork("rare-left automatic control", adjacency,
				rareLeftSmall.automatic(), rareLeftLarge.automatic())).doesNotThrowAnyException();
		softly.assertThatCode(() -> assertNearConstantWork("rare-left forced nestedLoop control", adjacency,
				rareLeftSmall.nestedLoop(), rareLeftLarge.nestedLoop())).doesNotThrowAnyException();
		softly.assertAll();
	}

	private UnionMeasurement measureUnion(boolean adjacency, int values, String query, String arm,
			boolean semanticVariants, SoftAssertions softly) throws Exception {
		Path actualPath = directory.resolve("union-actual-" + adjacency + "-" + arm + "-" + values);
		Path genericPath = directory.resolve("union-generic-" + adjacency + "-" + arm + "-" + values);
		LmdbStore actualStore = new LmdbStore(actualPath.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency));
		LmdbStore genericStore = new LmdbStore(genericPath.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		SailRepository actual = new SailRepository(actualStore);
		SailRepository generic = new SailRepository(genericStore);
		actual.init();
		generic.init();
		try {
			loadUnion(actual, values);
			loadUnion(generic, values);
			LmdbCompatibilityFixtures.assertPersistentStatementAuthority(actualStore, 8L * values + 3, 0);
			if (adjacency) {
				assertThat(actualStore.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS))
						.as(actualStore.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}

			try (var nativeConnection = actual.getConnection(); var genericConnection = generic.getConnection()) {
				List<BindingSet> expectedRows = expectedUnionRows(values, arm);
				TupleQuery genericQuery = genericConnection.prepareTupleQuery(query);
				((SailQuery) genericQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> expected = evaluate(genericQuery);
				assertThat(bag(expected)).as("generic %s alias result is the independently constructed exact bag", arm)
						.containsExactlyInAnyOrderEntriesOf(bag(expectedRows));

				TupleQuery nativeQuery = nativeConnection.prepareTupleQuery(query);
				((SailQuery) nativeQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> result = evaluate(nativeQuery);
				assertThat(bag(result)).as("native %s alias preserves the exact independent result", arm)
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				String telemetry = nativeQuery.explain(Explanation.Level.Telemetry).toString();
				assertThat(telemetry)
						.as("the UNION work measure comes from executed native telemetry")
						.startsWith("LMDB native physical plan (executed)")
						.contains("nativeInvocationsActual=1", "nativeExecutionPath=");
				WorkMetrics automatic = workMetrics(telemetry);
				CompletedLmdbWork automaticLmdb = completedLmdbWork(telemetry);
				assertThat(automatic.primaryWork())
						.as("executed UNION alias source/filter work must be observable\n%s", telemetry)
						.isPositive();
				softly.assertThat(automatic.filterEvaluations())
						.as("the repeatable selective FILTER must execute and report its work\n%s", telemetry)
						.isPositive();
				if (telemetry.contains("nativeExecutionPath=orderedDistinct")) {
					softly.assertThat(telemetry)
							.as("orderedDistinct must activate its serving runtime invocation\n%s", telemetry)
							.containsPattern("(?m)^\\h+strategy: orderedDistinct\\h*$");
				}

				SailTupleQuery forcedQuery = (SailTupleQuery) nativeConnection.prepareTupleQuery(query);
				forcedQuery.setForcedLmdbExecutionStrategy("nestedLoop");
				((SailQuery) forcedQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> forcedRows = evaluate(forcedQuery);
				assertThat(bag(forcedRows)).as("forced native route preserves the exact %s alias bag", arm)
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				String forcedTelemetry = forcedQuery.explain(Explanation.Level.Telemetry).toString();
				assertThat(forcedTelemetry)
						.as("the forced source-work control must execute the supported native tier")
						.startsWith("LMDB native physical plan (executed)")
						.contains("strategy: nestedLoop", "nativeInvocationsActual=1");
				WorkMetrics nestedLoop = workMetrics(forcedTelemetry);
				CompletedLmdbWork nestedLoopLmdb = completedLmdbWork(forcedTelemetry);
				assertThat(nestedLoop.primaryWork())
						.as("the forced route must report source/filter work\n%s", forcedTelemetry)
						.isPositive();

				Path evidence = Files.createDirectories(Path.of("target", "union-alias-work",
						"adjacency-" + adjacency + "-" + arm + "-size-" + values));
				Files.writeString(evidence.resolve("query.rq"), query);
				Files.writeString(evidence.resolve("results-and-work.txt"),
						"adjacency=" + adjacency + "\nsize=" + values + "\nindexes=spoc,posc\narm=" + arm + "\n"
								+ "expectedRows=" + canonicalRows(expected) + "\nactualRows=" + canonicalRows(result)
								+ "\n"
								+ "automaticWork=" + automatic + "\nforcedNestedLoopWork=" + nestedLoop + "\n"
								+ "automaticCompletedLmdbWork=" + automaticLmdb + "\n"
								+ "forcedCompletedLmdbWork=" + nestedLoopLmdb + "\n\n"
								+ "automatic telemetry:\n" + telemetry + "\nforced telemetry:\n" + forcedTelemetry);
				if (semanticVariants) {
					assertUnionSemanticVariants(nativeConnection, genericConnection, adjacency);
				}
				return new UnionMeasurement(automatic, nestedLoop, automaticLmdb, nestedLoopLmdb);
			}
		} finally {
			actual.shutDown();
			generic.shutDown();
		}
	}

	private Measurement measure(boolean adjacency, int values, boolean semanticVariants) throws Exception {
		Path actualPath = directory.resolve("actual-" + adjacency + "-" + values);
		Path genericPath = directory.resolve("generic-" + adjacency + "-" + values);
		LmdbStore actualStore = new LmdbStore(actualPath.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency));
		LmdbStore genericStore = new LmdbStore(genericPath.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		SailRepository actual = new SailRepository(actualStore);
		SailRepository generic = new SailRepository(genericStore);
		actual.init();
		generic.init();
		try {
			load(actual, values);
			load(generic, values);
			LmdbCompatibilityFixtures.assertPersistentStatementAuthority(actualStore, 2L * values + 3, 0);
			if (adjacency) {
				assertThat(actualStore.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS))
						.as(actualStore.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}

			try (var nativeConnection = actual.getConnection(); var genericConnection = generic.getConnection()) {
				TupleQuery nativeQuery = nativeConnection.prepareTupleQuery(BASE_QUERY);
				TupleQuery referenceQuery = genericConnection.prepareTupleQuery(BASE_QUERY);
				((SailQuery) nativeQuery).setLmdbResultCacheRequested(false);
				((SailQuery) referenceQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> expected = evaluate(referenceQuery);
				List<BindingSet> result = evaluate(nativeQuery);
				assertThat(bag(result)).as("native alias join must preserve the generic result bag")
						.containsExactlyInAnyOrderEntriesOf(bag(expected));

				String telemetry = nativeQuery.explain(Explanation.Level.Telemetry).toString();
				assertThat(telemetry)
						.as("the automatic source-work measurement must come from executed LMDB native telemetry")
						.startsWith("LMDB native physical plan (executed)")
						.contains("nativeInvocationsActual=1", "nativeExecutionPath=");
				long candidates = candidateRows(telemetry);
				long automaticScannedRows = scannedRows(telemetry);
				long automaticWork = candidates > 0 ? candidates : automaticScannedRows;
				String automaticWorkMetric = candidates > 0 ? "candidateRows" : "rowsScannedActual";
				assertThat(automaticWork)
						.as("the selected automatic native route must report candidate work or completed source scans\n%s",
								telemetry)
						.isPositive();

				SailTupleQuery nestedLoopQuery = (SailTupleQuery) nativeConnection.prepareTupleQuery(BASE_QUERY);
				nestedLoopQuery.setForcedLmdbExecutionStrategy("nestedLoop");
				((SailQuery) nestedLoopQuery).setLmdbResultCacheRequested(false);
				List<BindingSet> nestedLoopResult = evaluate(nestedLoopQuery);
				assertThat(bag(nestedLoopResult)).as("native nested-loop alias join preserves the generic result bag")
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				String nestedLoopTelemetry = nestedLoopQuery.explain(Explanation.Level.Telemetry).toString();
				assertThat(nestedLoopTelemetry)
						.as("the source-work control must execute the native nested-loop route")
						.startsWith("LMDB native physical plan (executed)")
						.contains("strategy: nestedLoop", "nativeInvocationsActual=1");
				long scannedRows = scannedRows(nestedLoopTelemetry);
				assertThat(scannedRows)
						.as("the native nested-loop control must expose completed source scan counts\n%s",
								nestedLoopTelemetry)
						.isPositive();

				Path evidence = Files.createDirectories(Path.of("target", "alias-join-source-work",
						"adjacency-" + adjacency + "-size-" + values));
				Files.writeString(evidence.resolve("query.rq"), BASE_QUERY);
				Files.writeString(evidence.resolve("result-and-work.txt"),
						"adjacency=" + adjacency + "\nvalues=" + values + "\nindexes=spoc,posc\n"
								+ "genericRows=" + expected.size() + "\nnativeRows=" + result.size() + "\n"
								+ "nativeCandidateRowsActual=" + candidates + "\n"
								+ "nativeSourceRowsScannedActual=" + automaticScannedRows + "\n"
								+ "nativeAutomaticWork=" + automaticWorkMetric + ":" + automaticWork + "\n"
								+ "nestedLoopSourceRowsScannedActual=" + scannedRows + "\n\n"
								+ "default execution:\n" + telemetry + "\nforced nested-loop source control:\n"
								+ nestedLoopTelemetry);
				if (semanticVariants) {
					assertSemanticVariants(nativeConnection, genericConnection);
				}
				return new Measurement(candidates, automaticScannedRows, automaticWork, automaticWorkMetric,
						scannedRows,
						telemetry, nestedLoopTelemetry);
			}
		} finally {
			actual.shutDown();
			generic.shutDown();
		}
	}

